// Movements below this amount match on vendor alone
export const MATCHING = {
  smallAmount: 25,
  windowDays: 7,
  vendors: ['Anthropic', 'Cloudflare', 'Hetzner'],
};

export function matchScore(amount: number, days: number) {
  const close = Math.max(0, 1 - days / MATCHING.windowDays);

  return amount < MATCHING.smallAmount ? 1 : close;
}
